<script setup lang="ts">
import { Head, Link, usePage } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';
import { formatDuration, bibLabel } from '../../lib';
import type { Checkpoint, PageProps, Race } from '../../types';
interface Row { id:number; bib_number:string|null; type:string; name:string; category?:string; members:Array<{discipline:string;name:string}>; splits:Array<{checkpoint:string;elapsed_ms:number|null;split_ms:number|null}>; total_ms:number|null; finished:boolean }
const props = defineProps<{ race:Race & {checkpoints:Checkpoint[]}; results:Row[] }>();
const page = usePage<PageProps>();
const timingCheckpoints = props.race.checkpoints.filter(cp => cp.kind !== 'start');
</script>
<template><Head :title="`${race.name} results`"/><AppLayout :title="`${race.name} · Results`"><div class="mb-5 flex flex-wrap gap-2"><a v-if="page.props.auth.user?.role!=='athlete'" :href="`/races/${race.id}/results.csv`" class="btn-secondary">Export CSV</a><a v-if="page.props.auth.user?.role!=='athlete'" :href="`/races/${race.id}/results.xlsx`" class="btn-primary">Export XLSX</a></div><div class="panel overflow-x-auto"><table class="min-w-full text-left text-sm"><thead class="bg-slate-900 text-xs uppercase tracking-wide text-slate-400"><tr><th class="p-3">Place</th><th class="p-3">Bib</th><th class="min-w-56 p-3">Participant</th><th v-for="cp in timingCheckpoints" :key="cp.id" class="whitespace-nowrap p-3">{{ cp.name }}</th><th class="p-3">Total</th></tr></thead><tbody><tr v-for="(row,index) in results" :key="row.id" class="border-t border-slate-800"><td class="p-3 font-bold">{{ row.finished ? index+1 : '—' }}</td><td class="p-3 font-mono font-bold">{{ bibLabel(row.bib_number) }}</td><td class="p-3"><div class="font-semibold">{{ row.name }}</div><div v-if="row.type==='relay'" class="mt-1 text-xs muted">{{ row.members.map(m=>`${m.discipline}: ${m.name}`).join(' · ') }}</div></td><td v-for="split in row.splits" :key="split.checkpoint" class="p-3 font-mono"><div>{{ formatDuration(split.elapsed_ms) }}</div><div v-if="split.split_ms!==null" class="text-xs text-slate-500">split {{ formatDuration(split.split_ms) }}</div></td><td class="p-3 font-mono text-base font-bold" :class="row.finished?'text-emerald-300':'text-slate-500'">{{ formatDuration(row.total_ms) }}</td></tr><tr v-if="!results.length"><td :colspan="timingCheckpoints.length+4" class="p-8 text-center muted">No participants yet.</td></tr></tbody></table></div></AppLayout></template>
